CREATE OR REPLACE FUNCTION public.notify_on_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.notify(
    new.reviewee_id, 'review', 'engagement',
    public.actor_name(new.reviewer_id) || ' left you a ' || new.rating || '-star review',
    left(coalesce(new.body, ''), 140), '/orders/' || new.order_id, new.reviewer_id
  );
  return new;
end;
$function$;

grant execute on function public.notify_on_review() to anon;
grant execute on function public.notify_on_review() to authenticated;
grant execute on function public.notify_on_review() to public;
